import React, { useState } from 'react';
import { Button } from "@/components/ui/button";
import { Sparkles, Loader2, RefreshCw } from 'lucide-react';

export default function TraceReflection({ belief, onSave }) {
  const [isLoading, setIsLoading] = useState(false);
  const [reflection, setReflection] = useState(null);
  const [error, setError] = useState(null);

  const generateReflection = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 30000); // 30 second timeout

      const response = await fetch('https://api.together.xyz/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${process.env.REACT_APP_TOGETHER_API_KEY}`
        },
        body: JSON.stringify({
          model: 'meta-llama/Meta-Llama-3.1-8B-Instruct-Turbo',
          messages: [{
            role: 'user',
            content: `When responding to a user's belief entry, follow these rules strictly:
              1. Be gentle and non-judgmental.
              2. Avoid taking a stance or expressing a personal opinion.
              3. Focus on clarifying the user's thoughts and feelings.
              4. Use open-ended questions to encourage the user to think critically.
              5. Provide a summary of the user's main points.
              6. Identify any assumptions or biases in the user's thinking.
              7. Offer suggestions for further reflection or exploration.
              8. Keep your response concise and easy to understand.
              9. Use a neutral tone and avoid using jargon or technical terms.
              10. Remember that your goal is to assist the user in their reflection, not to provide a definitive answer or solution.

              Now, please respond to this user's belief entry: ${belief.content}`
          }]
        }),
      });

      console.log('Ollama response:', response);

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      const reflectionContent = data.choices?.[0]?.message?.content || "Reflection unavailable";
      setReflection(reflectionContent);

    } catch (err) {
      if (err.name === "AbortError") {
        setError("Request timed out. Please try again.");
      } else {
        console.error(err);
        setError("Couldn't generate reflection. Please try again.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!reflection) return;

    const newTraceReflection = {
      date: new Date().toISOString(),
      content: reflection,
    };

    const existingReflections = belief?.ai_reflections || [];

    await onSave({
      ai_reflections: [...existingReflections, newTraceReflection],
    });
  };

  if (!reflection && !isLoading) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-xl bg-white/80 flex items-center justify-center flex-shrink-0">
            <Sparkles className="w-5 h-5 text-[#5C6B5E]" />
          </div>
          <div className="flex-1">
            <h3 className="font-medium text-slate-800 mb-1">
              Trace Reflection
            </h3>
            <p className="text-sm text-slate-600 mb-4">
              Get a gentle reflection to help clarify your thinking. Trace won't judge or try to change your mind.
            </p>
            <Button
              onClick={generateReflection}
              disabled={isLoading}
              className="bg-white hover:bg-slate-50 text-[#5C6B5E] border border-[#5C6B5E]/20 rounded-xl"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              Reflect with Trace
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
        <div className="flex items-center justify-center gap-3 py-8">
          <Loader2 className="w-5 h-5 animate-spin text-[#5C6B5E]" />
          <span className="text-slate-600">Thinking gently...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 rounded-2xl p-6">
        <p className="text-red-600 text-sm mb-3">{error}</p>
        <Button
          onClick={generateReflection}
          variant="outline"
          size="sm"
          className="text-red-600 border-red-200"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          Try again
        </Button>
      </div>
    );
  }

  return (
    <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6 space-y-4">
      <div className="flex items-center gap-2">
        <Sparkles className="w-4 h-4 text-[#5C6B5E]" />
        <span className="text-sm font-medium text-[#5C6B5E]">
          AI Reflection
        </span>
      </div>

      {reflection?.summary && (
        <div>
          <p className="text-sm text-slate-500 mb-1">In other words:</p>
          <p className="text-slate-700 leading-relaxed">
            {reflection.summary}
          </p>
        </div>
      )}

      {reflection?.clarifying_questions?.length > 0 && (
        <div>
          <p className="text-sm text-slate-500 mb-2">
            Questions to consider:
          </p>
          <ul className="space-y-2">
            {reflection.clarifying_questions.map((q, i) => (
              <li key={i} className="flex gap-2 text-slate-700">
                <span className="text-[#5C6B5E]">•</span>
                <span className="leading-relaxed">{q}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {reflection?.assumptions_noticed && (
        <div>
          <p className="text-sm text-slate-500 mb-1">
            Possible assumptions:
          </p>
          <p className="text-slate-700 leading-relaxed">
            {reflection.assumptions_noticed}
          </p>
        </div>
      )}

      <div className="flex gap-2 pt-2">
        <Button
          onClick={generateReflection}
          variant="outline"
          size="sm"
          className="text-slate-600 border-slate-200 rounded-lg"
        >
          <RefreshCw className="w-4 h-4 mr-1" />
          New reflection
        </Button>

        <Button
          onClick={handleSave}
          size="sm"
          className="bg-[#5C6B5E] hover:bg-[#4a574c] text-white rounded-lg"
        >
          Save this
        </Button>
      </div>
    </div>
  );
}
